import json
from html import escape
from pathlib import Path

root = Path(__file__).parent
refs = json.loads((root / 'references.json').read_text())
cards = []
for r in refs:
    video = f'<details class="motion"><summary>查看官方动态结构演示</summary><video controls muted playsinline preload="none" src="{escape(r["video"], quote=True)}"></video></details>' if r.get('video') else ''
    extra = f'<a href="{r["extraUrl"]}" target="_blank" rel="noreferrer">TXC 官方案例 ↗</a><img class="extra" src="{r["extra"]}" alt="N3 TXC：项目内保存的官方页面截图">' if r.get('extra') else ''
    cards.append(f'''<article class="case" data-category="{r['category']}" id="{r['id']}">
      <div class="visual"><a href="{escape(r['image'],quote=True)}" target="_blank" rel="noreferrer" aria-label="打开 {r['name']} 原图"><img src="{escape(r['image'],quote=True)}" alt="{r['name']} 官方案例参考图" loading="eager"></a><span class="media-state">原图加载中</span></div>
      <div class="case-body"><div class="eyebrow">{r['studio']} <span>{r['priority']}</span></div>
      <h2>{r['name']}</h2><p class="thesis">{r['label']}</p>
      <dl><dt>原作怎么做</dt><dd>{r['fact']}</dd><dt>我们学什么 <small>设计推导</small></dt><dd>{r['learn']}</dd><dt>适用边界</dt><dd>{r['avoid']}</dd></dl>
      <a class="source" href="{r['url']}" target="_blank" rel="noreferrer">查看设计机构原作 ↗</a>{video}{extra}
      <details class="evidence"><summary>来源与核验范围</summary><p>{r['evidence']}</p></details></div></article>''')

html = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TokenMini · 非常规 Logo 参考研究</title>
<style>
:root{color-scheme:dark;--bg:#111413;--surface:#1a1e1c;--ink:#f1f2e9;--muted:#b4bcb5;--line:#38423b;--accent:#a9efd0}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}a{color:var(--accent);text-underline-offset:5px}a:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.wrap{max-width:1400px;margin:auto;padding:48px 36px 88px}.mast{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:20px;color:var(--muted);font-size:13px;letter-spacing:.05em}header{padding:58px 0 34px;max-width:1000px}h1{font-size:clamp(34px,5vw,65px);font-weight:500;letter-spacing:-.04em;line-height:1.2;margin:0 0 24px}header p{max-width:860px;font-size:19px;color:var(--muted)}.lead{color:var(--ink)}.factline{font-size:13px;color:var(--muted)}.principles{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin:24px 0 44px}.principles div{border-top:1px solid var(--line);padding-top:17px}.principles strong{display:block;font-size:18px;font-weight:550}.principles p{font-size:14px;color:var(--muted);margin:6px 0}.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px 0 28px}button{font:inherit;font-size:14px;cursor:pointer;border:1px solid var(--line);border-radius:30px;background:none;color:var(--muted);padding:8px 17px}button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:#112119}.count{margin-left:auto;color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:32px;align-items:start}.case{min-width:0;background:var(--surface);border:1px solid var(--line)}.case[hidden]{display:none}.visual{position:relative;aspect-ratio:16/10;background:#e7e7e2;overflow:hidden;display:grid;place-items:center}.visual a{display:block;width:100%;height:100%}.visual img{width:100%;height:100%;object-fit:contain;display:block}.media-state{position:absolute;bottom:10px;left:12px;background:#111b;padding:4px 9px;border-radius:4px;font-size:11px;color:white;pointer-events:none}.visual.failed{background:#242d27}.visual.failed a{display:none}.visual.failed .media-state{position:static;font-size:14px;background:none;text-align:center;padding:30px}.case-body{padding:25px 28px}.eyebrow{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;gap:12px}.eyebrow span{color:var(--accent)}h2{font-size:30px;line-height:1.3;letter-spacing:-.02em;margin:12px 0 5px;font-weight:550}.thesis{font-size:17px;color:var(--accent);margin:0 0 23px}dl{margin:0}dt{font-size:12px;color:var(--muted);margin-top:17px}dt small{margin-left:8px;opacity:.8}dd{margin:4px 0 0;font-size:15px}.source{display:inline-block;margin-top:25px;font-size:14px}.evidence{color:var(--muted);font-size:12px;margin-top:20px}summary{cursor:pointer}.motion{margin:20px 0;font-size:14px}.motion video{display:block;width:100%;max-height:520px;margin-top:12px;background:black}.extra{width:100%;margin-top:15px}.decision{margin-top:64px;border-top:1px solid var(--line);padding-top:34px}.decision h2{font-size:30px;margin-bottom:10px}.routes{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin-top:24px}.route{border-top:3px solid var(--accent);padding-top:18px}.route h3{font-size:21px;font-weight:550;margin:0 0 12px}.route p{font-size:15px;color:var(--muted)}.route small{font-size:13px;color:var(--accent)}footer{font-size:13px;color:var(--muted);margin-top:52px;border-top:1px solid var(--line);padding-top:24px}footer p{max-width:950px}.notice{padding:18px 0;font-size:14px;color:var(--muted)}@media(max-width:760px){.wrap{padding:24px 20px 50px}.mast{font-size:11px}.principles,.grid,.routes{grid-template-columns:1fr}.principles{gap:15px}.grid{gap:24px}.count{margin-left:0;width:100%}.case-body{padding:22px}header{padding:36px 0 18px}header p{font-size:17px}.visual{aspect-ratio:4/3}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style><body><main class="wrap"><div class="mast"><span>TOKENMINI / BRAND RESEARCH</span><span>2026.09.20 · 研究阶段</span></div>
<p><a href="reset-v2/index.html">本轮草案已全部否决，查看第二轮视觉研究 →</a></p><header><h1>让造型有自己的逻辑。</h1><p class="lead">非常规 Logo 的参考研究：从产品主题出发，找到一种独特的结构，再让它延伸为图标、字标、动效与材质。</p><p class="factline">以下是 7 组真实作品参考，包含不同年份的案例。关于 TokenMini 的适配度和创作路线是本次设计判断；本页为创作前研究，研究后的第一轮草案另页展示。</p></header>
<p><a href="concepts.html">查看研究后的三张结构草案与评审 →</a></p><section class="principles"><div><strong>保留你的识别偏好</strong><p>圆环或循环感、绿色片段、隐含的 T；避开突出的尖角。</p></div><div><strong>先判断轮廓是否独特</strong><p>把标准 T 放进圆圈，只解决了组合问题，还没有解决品牌特征。</p></div><div><strong>让材质有结构可依附</strong><p>单色与小尺寸先成立，再延伸你认可的金属和绿色玻璃。</p></div></section>
<nav class="filters" aria-label="参考分类"><button data-filter="all" aria-pressed="true">全部参考</button><button data-filter="form" aria-pressed="false">造型与字母</button><button data-filter="system" aria-pressed="false">系统与变化</button><button data-filter="material" aria-pressed="false">材质与空间</button><span class="count" aria-live="polite">7 组参考</span></nav>
<section class="grid">''' + '\n'.join(cards) + '''</section>
<section class="decision"><div class="eyebrow">从参考走向创作 · 原始创作简报</div><h2>建议探索三种结构，优先 A 与 B。</h2><p class="notice">参考的是构造方法，不移植任何品牌的独特轮廓。三条路线都需接受单色、小尺寸与同领域相似性检查。</p><div class="routes"><div class="route"><small>A / 优先</small><h3>一体折转的环</h3><p>圆环自身折转或对接，在连续轮廓中留下 T。用圆润转折消除突兀尖角，绿色段成为结构的一部分。</p><p>借鉴 Modyfi 的一体结构思路，再接 N3 材质。避免走成常见无限环、旋涡。</p></div><div class="route"><small>B / 主题最直接</small><h3>由分段单元形成的环</h3><p>两到三个计量单元形成近圆的整体，空隙暗示 T。让 Token 的分段与聚合成为造型依据。</p><p>借鉴 Cohere 的组合关系和 Graphcore 的生成规则。避免平均分割的饼图和加载标记。</p></div><div class="route"><small>C / 对照探索</small><h3>两个截面共同围出 T</h3><p>两个相互呼应的弧形截面，通过不同曲率围出 T 形空隙，兼顾圆环感与陌生感。</p><p>用两个部分汇聚到一个工具的隐喻表达 AI 用量与 Mac 状态。避免眼睛、盾牌或导航标的误读。</p></div></div></section>
<footer><p>本页是参考资料，外部作品权利归原作者。官方原图通过网络加载，未下载或改造；若图片无法载入，请点该项的原作链接。N3 两张图来自项目既有的官方网页截图。</p><p>动态片段需手动播放。本次未逐帧审查全部影片，未做市场识别实验。Logo 里的固定绿色片段将作为品牌识别；实际额度、错误和数据状态仍需由界面明确表达。</p><p><a href="README.md">完整研究与创作简报</a> · 补充阅读：<a href="https://www.pentagram.com/work/isomorphic-labs" target="_blank" rel="noreferrer">Isomorphic Labs</a> / <a href="https://www.pentagram.com/work/twelvelabs" target="_blank" rel="noreferrer">TwelveLabs</a></p></footer></main>
<script>
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.case').forEach(c=>{c.hidden=f!=='all'&&c.dataset.category!==f;if(!c.hidden)n++});document.querySelector('.count').textContent=n+' 组参考'}));
document.querySelectorAll('.visual img').forEach(img=>{const set=ok=>{const v=img.closest('.visual');v.classList.toggle('failed',!ok);v.querySelector('.media-state').textContent=ok?'参考原作 · 点击放大':'原图暂时无法载入，请打开下方官方案例'};img.addEventListener('load',()=>set(img.naturalWidth>0));img.addEventListener('error',()=>set(false));if(img.complete)set(img.naturalWidth>0)});
document.querySelectorAll('.motion').forEach(d=>d.addEventListener('toggle',()=>{if(!d.open)d.querySelector('video').pause()}));
</script></body></html>'''
(root / 'index.html').write_text(html)
print(f'Built {root / "index.html"}: {len(refs)} references')
